        if (start > end) {
            return 1;
        }

        int count = 0;
        for (int i = start; i <= end; i++) {
            int leftCount = countTrees(start, i - 1);
            int rightCount = countTrees(i + 1, end);
            count += leftCount * rightCount;
        }

        return count;
    }
}

