public int countRestrictedPaths(int n, int[][] edges, int[] restricted) {
    // Create an adjacency list to represent the graph
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }

    // Add edges to the graph
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    // Create a set to store restricted nodes
    Set<Integer> restrictedSet = new HashSet<>();
    for (int node : restricted) {
        restrictedSet.add(node);
    }

    // Perform a depth-first search to count the number of restricted paths
    int count = 0;
    boolean[] visited = new boolean[n];
    for (int i = 0; i < n; i++) {
        if (!restrictedSet.contains(i) && !visited[i]) {
            count += dfs(graph, restrictedSet, visited, i);
        }
    }

    return count;
}

private int dfs(List<List<Integer>> graph, Set<Integer> restrictedSet, boolean[] visited, int node) {
    visited[node] = true;
    int count = 1;
    for (int neighbor : graph.get(node)) {
        if (!restrictedSet.contains(neighbor) && !visited[neighbor]) {
            count += dfs(graph, restrictedSet, visited, neighbor);
        }
    }
    return count;
}

