public boolean canFinish(int numCourses, int[][] prerequisites) {
    // Create an adjacency list to represent the graph
    List<List<Integer>> adjList = new ArrayList<>();
    for (int i = 0; i < numCourses; i++) {
        adjList.add(new ArrayList<>());
    }

    // Populate the adjacency list with the prerequisites
    for (int[] prerequisite : prerequisites) {
        adjList.get(prerequisite[0]).add(prerequisite[1]);
    }

    // Perform a topological sort to check for cycles
    boolean[] visited = new boolean[numCourses];
    boolean[] inStack = new boolean[numCourses];
    for (int i = 0; i < numCourses; i++) {
        if (!visited[i] && hasCycle(adjList, visited, inStack, i)) {
            return false;
        }
    }

    return true;
}

private boolean hasCycle(List<List<Integer>> adjList, boolean[] visited, boolean[] inStack, int course) {
    if (inStack[course]) {
        return true;
    }
    if (visited[course]) {
        return false;
    }

    visited[course] = true;
    inStack[course] = true;

    for (int neighbor : adjList.get(course)) {
        if (hasCycle(adjList, visited, inStack, neighbor)) {
            return true;
        }
    }

    inStack[course] = false;
    return false;
}

