                return 0;
            }
        }
        int count = 0;
        for (int num : nums) {
            if (num > gcd) {
                break;
            }
            count++;
        }
        return count;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

