private int findIndex(List<Integer> sorted, int num) {
    int left = 0, right = sorted.size();
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (sorted.get(mid) < num) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}

