import java.util.LinkedList;
import java.util.Queue;
import java.util.Set;

public int minMutation(String startGene, String endGene, String[] bank) {
    Set<String> dict = new HashSet<>();
    for (String gene : bank) {
        dict.add(gene);
    }
    if (!dict.contains(endGene)) return -1;

    Queue<String> q = new LinkedList<>();
    q.offer(startGene);
    int steps = 0;

    while (!q.isEmpty()) {
        int size = q.size();
        for (int i = 0; i < size; ++i) {
            String currentGene = q.poll();
            if (currentGene.equals(endGene)) return steps;

            char[] charArray = currentGene.toCharArray();
            for (int j = 0; j < charArray.length; ++j) {
                char originalChar = charArray[j];
                for (char c = 'A'; c <= 'Z'; ++c) {
                    if (c == originalChar) continue;
                    charArray[j] = c;
                    String newGene = new String(charArray);
                    if (dict.remove(newGene)) {
                        q.offer(newGene);
                    }
                }
                charArray[j] = originalChar;
            }
        }
        ++steps;
    }
    return -1;
}

