import java.util.*;

public class Solution {
    public int findMinMoves(int[] nums) {
        int n = nums.length;
        int[] prefixSum = new int[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }
        int minMoves = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int leftSum = prefixSum[i];
            int rightSum = prefixSum[n] - prefixSum[i + 1];
            int leftMoves = (i + 1) * nums[i] - leftSum;
            int rightMoves = (n - i - 1) * nums[i] - rightSum;
            minMoves = Math.min(minMoves, Math.max(leftMoves, rightMoves));
        }
        return minMoves;
    }
}

